// ============================================================
// CONFIGURACAO DO TEMPLATE - ALTERE SOMENTE ESTA SECAO
// ============================================================
const UrlBlog = "https://seu-dominio.com.br";
const NomeEmpresa = "COLOQUE O NOME DA SUA EMPRESA AQUI";
const Nicho = "COLOQUE SEU NICHO AQUI";
const Publico = "COLOQUE SEU PUBLICO-ALVO AQUI";
const Tamanho = "G (1500 a 2200 palavras): 8 a 11 secoes H2";

// IDs do WordPress. Categoria 1 normalmente e "Sem categoria".
// Altere para os IDs do seu WordPress antes de ativar o workflow.
const CategoriaId = 1;
const FeaturedMediaId = 0; // 0 = sem imagem destacada
const SlugArtigos = "artigos";
const SlugContato = "contato";

// Cadastre aqui seus temas.
// "segSlug" pode ser a pagina interna relacionada ao tema/segmento.
const temas = [
  {
    tema: "COLOQUE O TITULO/TEMA DO ARTIGO 1 AQUI",
    foco: "COLOQUE A PALAVRA-CHAVE DE FOCO 1 AQUI",
    seg: "COLOQUE O SEGMENTO 1 AQUI",
    segSlug: "COLOQUE-O-SLUG-DA-PAGINA-RELACIONADA-1"
  },
  {
    tema: "COLOQUE O TITULO/TEMA DO ARTIGO 2 AQUI",
    foco: "COLOQUE A PALAVRA-CHAVE DE FOCO 2 AQUI",
    seg: "COLOQUE O SEGMENTO 2 AQUI",
    segSlug: "COLOQUE-O-SLUG-DA-PAGINA-RELACIONADA-2"
  },
  {
    tema: "COLOQUE O TITULO/TEMA DO ARTIGO 3 AQUI",
    foco: "COLOQUE A PALAVRA-CHAVE DE FOCO 3 AQUI",
    seg: "COLOQUE O SEGMENTO 3 AQUI",
    segSlug: "COLOQUE-O-SLUG-DA-PAGINA-RELACIONADA-3"
  }
];

// ============================================================
// LOGICA DO WORKFLOW - NAO PRECISA ALTERAR
// ============================================================
const data = $getWorkflowStaticData('global');
let idx = typeof data.temaIndex === 'number' ? data.temaIndex : 0;
if (idx >= temas.length || idx < 0) idx = 0;
const t = temas[idx];
data.temaIndex = (idx + 1) % temas.length;

function slugify(s){
  return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')
    .split('-').filter(Boolean).slice(0,6).join('-');
}

const FocusKeyword = t.foco;
const FocusKeywordSlug = slugify(t.foco);
const FocusKeywordTitleCase = t.foco
  .split(' ')
  .map(w => w ? w.charAt(0).toUpperCase() + w.slice(1) : w)
  .join(' ');

return [{
  json: {
    PalavraChave: t.tema,
    FocusKeyword,
    FocusKeywordSlug,
    FocusKeywordTitleCase,
    Segmento: t.seg,
    SegSlug: t.segSlug,
    UrlBlog,
    NomeEmpresa,
    Nicho,
    Publico,
    Tamanho,
    CategoriaId,
    FeaturedMediaId,
    SlugArtigos,
    SlugContato,
    TemaIndex: idx,
    TemaTotal: temas.length
  }
}];

