for (const item of items) {
  let markdownText = (item.json.ConteudoMark ?? "").toString();
  markdownText = markdownText.replace(/\\n/g, "\n");
  markdownText = markdownText.replace(/\n{3,}/g, "\n\n");
  markdownText = markdownText.replace(/[ \t]+\n/g, "\n");

  function parseMarkdown(text) {
    const lines = text.split('\n');
    let html = '';
    let inList = null;
    const tableSeparatorRegex = /^\s*\|?(?:\s*:?-+:?\s*\|)+\s*$/;
    const hrRegex = /^\s*(?:-{3,}|\*{3,}|_{3,})\s*$/;
    let paragraphBuffer = [];
    function flushParagraph() {
      if (paragraphBuffer.length) {
        if (inList) { html += `</${inList}>`; inList = null; }
        const merged = paragraphBuffer.join(' ').replace(/\s+/g, ' ').trim();
        html += `<p>${parseInlines(merged)}</p>`;
        paragraphBuffer = [];
      }
    }
    for (let i = 0; i < lines.length; i++) {
      let line = lines[i];
      if (line.includes('|') && i + 1 < lines.length && tableSeparatorRegex.test(lines[i + 1])) {
        flushParagraph();
        if (inList) { html += `</${inList}>`; inList = null; }
        const headers = line.split('|').map(h => h.trim()).filter(Boolean);
        const bodyRows = [];
        i += 2;
        while (i < lines.length && lines[i].includes('|') && lines[i].trim() !== '') {
          bodyRows.push(lines[i].split('|').map(c => c.trim()).filter(Boolean));
          i++;
        }
        i--;
        html += '<table><thead><tr>';
        headers.forEach(header => { html += `<th>${parseInlines(header)}</th>`; });
        html += '</tr></thead><tbody>';
        bodyRows.forEach(row => {
          html += '<tr>';
          for (let j = 0; j < headers.length; j++) {
            const cellContent = row[j] ? parseInlines(row[j]) : '';
            html += `<td>${cellContent}</td>`;
          }
          html += '</tr>';
        });
        html += '</tbody></table>';
        continue;
      }
      const headerMatch = line.match(/^(#{1,6})\s+(.*)$/);
      if (headerMatch) {
        flushParagraph();
        if (inList) { html += `</${inList}>`; inList = null; }
        const level = headerMatch[1].length;
        const content = parseInlines(headerMatch[2]);
        html += `<h${level}>${content}</h${level}>`;
        continue;
      }
      if (hrRegex.test(line)) { continue; }
      const ulMatch = line.match(/^\s*[-*]\s+(.*)$/);
      const olMatch = line.match(/^\s*\d+\.\s+(.*)$/);
      if (ulMatch || olMatch) {
        flushParagraph();
        const listType = ulMatch ? 'ul' : 'ol';
        const content = parseInlines(ulMatch ? ulMatch[1] : olMatch[1]);
        if (inList !== listType) {
          if (inList) html += `</${inList}>`;
          html += `<${listType}>`;
          inList = listType;
        }
        html += `<li>${content}</li>`;
        continue;
      }
      if (inList && line.trim() === '') { html += `</${inList}>`; inList = null; continue; }
      if (line.trim() === '') { flushParagraph(); } else { paragraphBuffer.push(line.trim()); }
    }
    flushParagraph();
    if (inList) html += `</${inList}>`;
    return html;
  }
  function parseInlines(text) {
    if (!text) return '';
    return text
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.+?)\*/g, '<em>$1</em>')
      .replace(/~~(.+?)~~/g, '<del>$1</del>')
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
  }
  item.json.ConvertHtml = parseMarkdown(markdownText);
}
return items;

